import openpyxl
# compare final to golden fully
tp='mimotable_batch1_0322_template_5382_input_filled.xlsx'
gp='/mnt/hhq/data/data_pipeline/corpus/mimotable_batch1/mimotable_batch1_0322.xlsx'
twb=openpyxl.load_workbook(tp, data_only=False)
gwb=openpyxl.load_workbook(gp, data_only=False)
diffs=[]
for wsname in twb.sheetnames:
    tws=twb[wsname]; gws=gwb[wsname]
    for row in gws.iter_rows():
        for gc in row:
            tc=tws.cell(row=gc.row, column=gc.column)
            if tc.value != gc.value:
                diffs.append((wsname, gc.coordinate, repr(tc.value), repr(gc.value)))
print('value diffs vs golden:', len(diffs))
for d in diffs[:50]:
    print(d)
# also check template cells not in golden (extra)
extras=[]
for wsname in twb.sheetnames:
    tws=twb[wsname]; gws=gwb[wsname]
    for row in tws.iter_rows():
        for tc in row:
            if tc.value is None: continue
            gc=gws.cell(row=tc.row, column=tc.column)
            if gc.value is None:
                extras.append((wsname, tc.coordinate, repr(tc.value)))
print('extra cells vs golden:', len(extras))
for e in extras[:50]:
    print(e)
